test('[picker] every real selection_spec opens a picker and completes a draft', () => {
  const covered = new Set();

  for (const testCase of PICKER_CASES) {
    const offer = toMissionOffer(offerByMission(testCase.missionId));
    const label = `${testCase.missionId} (${offer.interaction})`;
    covered.add(offer.interaction);

    assert.equal(offer.interaction, testCase.kind, `${label}: wrong family`);
    // Whatever the picker needs to render is on the offer, not left on a raw
    // spec the component would have to interpret.
    assert.ok(
      isDraftComplete(offer, testCase.draft),
      `${label}: a representative draft must satisfy the Continue gate`
    );

    const payload = toSelectionPayload(testCase.draft, offer);
    assertWirePayload(payload, testCase.kind, label);
    assert.deepEqual(payload, testCase.expect, `${label}: wrong wire payload`);
  }

  assert.deepEqual(
    [...covered].sort(),
    [...INTERACTIONS].sort(),
    'all five interaction families must be exercised'
  );
});

