test('[http] requests carry the app bearer token and the documented shapes', async () => {
  const stub = stubFetch('open');
  const gateway = createHttpMissionGateway({
    baseUrl: '/api',
    fetchImpl: stub.impl,
    getToken: () => 'test-token',
  });

  await gateway.getHome({ eventId: 999, card: CARD });
  const homeCall = stub.calls.at(-1);
  assert.equal(homeCall.url, '/api/missions/home?event_id=999');
  assert.equal(homeCall.method, 'GET');
  assert.equal(homeCall.headers.Authorization, 'Bearer test-token');

  const wire = offerByMission('CARD-V2-H-003');
  const offer = toMissionOffer(wire);
  await gateway.select({
    eventId: 999,
    slot: 2,
    offer,
    selection: { kind: 'TARGET_FIGHTER', boutId: 101, corner: 'red', method: 'KO/TKO', round: 2 },
  });
  const selectCall = stub.calls.at(-1);
  assert.equal(selectCall.url, '/api/missions/select');
  assert.equal(selectCall.method, 'POST');

  const body = JSON.parse(selectCall.body);
  assert.equal(body.event_id, 999);
  assert.equal(body.slot, 2, 'the wire is one-based; there is no slot_index');
  assert.equal(body.slot_index, undefined);
  assert.equal(body.offer_id, wire.offer_id, 'select addresses the offer');
  assert.equal(body.mission_id, undefined, 'the mission id is not the address');
  assert.deepEqual(body.selection, {
    kind: 'TARGET_FIGHTER',
    bout_id: 101,
    corner: 'red',
    method: 'KO_TKO',
    round: 2,
  });

  await gateway.acknowledgeCelebration('cel-1');
  const ackCall = stub.calls.at(-1);
  assert.equal(ackCall.url, '/api/missions/celebrations/cel-1/ack');
  assert.equal(ackCall.method, 'POST');
});

test('[http] the request satisfies every field the backend reported missing', async () => {
  // The generator captured a REAL pydantic 422 for the body the broken frontend
  // used to send. The fields it called "missing" are exactly the fields the
  // current body must contain — the backend defines the list, not this test.
  const missing = PAYLOADS.errors.legacy_frontend_body_422.detail
    .filter((entry) => entry.type === 'missing')
    .map((entry) => entry.loc[entry.loc.length - 1]);
  assert.ok(missing.length > 0, 'the captured 422 must actually list missing fields');

  const stub = stubFetch('open');
  const gateway = createHttpMissionGateway({
    baseUrl: '/api',
    fetchImpl: stub.impl,
    getToken: () => 'test-token',
  });
  await gateway.select({
    eventId: 999,
    slot: 1,
    offer: toMissionOffer(offerByMission('CARD-V2-E-004')),
    selection: { kind: 'AUTO' },
  });

  const body = JSON.parse(stub.calls.at(-1).body);
  for (const field of missing) {
    assert.ok(field in body, `the body is still missing "${field}" — this is the original 422`);
  }
  assert.match(
    body.idempotency_key,
    /^[A-Za-z0-9._:-]{8,128}$/,
    'the key must satisfy SelectMissionCommand'
  );
});

test('[http] retrying the same selection reuses one idempotency key', async () => {
  const stub = stubFetch('open');
  const gateway = createHttpMissionGateway({
    baseUrl: '/api',
    fetchImpl: stub.impl,
    getToken: () => 'test-token',
  });
  const offer = toMissionOffer(offerByMission('CARD-V2-E-001'));
  const request = {
    eventId: 999,
    slot: 1,
    offer,
    selection: { kind: 'TARGET_FIGHTER', boutId: 101, corner: 'red' },
  };

  await gateway.select(request);
  await gateway.select(request);

  const bodies = stub.calls
    .filter((call) => call.url.includes('/missions/select'))
    .map((call) => JSON.parse(call.body));
  assert.equal(bodies.length, 2);
  assert.equal(
    bodies[0].idempotency_key,
    bodies[1].idempotency_key,
    'a retry must replay the receipt instead of creating a second assignment'
  );

  // A DIFFERENT selection must not collide onto that key: the backend answers
  // IDEMPOTENCY_CONFLICT when one key is reused with another request.
  const otherCorner = idempotencyKeyFor({
    eventId: 999,
    slot: 1,
    offerId: offer.offerId,
    selection: { kind: 'TARGET_FIGHTER', bout_id: 101, corner: 'blue' },
  });
  assert.notEqual(bodies[0].idempotency_key, otherCorner);

  // A caller may still supply its own.
  await gateway.select({ ...request, idempotencyKey: 'caller-supplied-key' });
  assert.equal(JSON.parse(stub.calls.at(-1).body).idempotency_key, 'caller-supplied-key');
});

