test('[http] mission error codes survive the detail envelope', async () => {
  const cases = [
    ['slot_locked_409', 409, 'SLOT_LOCKED'],
    ['offer_not_found_409', 409, 'OFFER_NOT_FOUND'],
    ['already_selected_409', 409, 'ALREADY_SELECTED'],
    ['idempotency_conflict_409', 409, 'IDEMPOTENCY_CONFLICT'],
    ['invalid_selection_409', 409, 'INVALID_SELECTION'],
    ['card_not_found_404', 404, 'NOT_AVAILABLE'],
  ];

  for (const [fixtureKey, status, expected] of cases) {
    const body = PAYLOADS.errors[fixtureKey];
    const gateway = createHttpMissionGateway({
      baseUrl: '/api',
      fetchImpl: async () => json(body, status),
      getToken: () => 'test-token',
    });

    await assert.rejects(
      () =>
        gateway.select({
          eventId: 999,
          slot: 1,
          offer: THROWAWAY_OFFER,
          selection: { kind: 'AUTO' },
        }),
      (error) => {
        assert.ok(error instanceof MissionGatewayError, `${fixtureKey}: wrong error type`);
        assert.equal(error.code, expected, `${fixtureKey}: reading detail.code failed`);
        assert.equal(error.message, body.detail.message, `${fixtureKey}: message lost`);
        return true;
      }
    );
  }
});

