function adminStub() {
  const calls = [];
  const control = { state: 'OPEN' };
  const impl = async (url, init = {}) => {
    const path = String(url);
    const method = init.method ?? 'GET';
    calls.push({ path, method, body: init.body });

    if (path.includes('/admin/missions/cards/')) {
      const action = path.split('/').pop();
      if (method === 'POST') {
        control.state =
          action === 'close' ? 'CLOSED' : action === 'void' ? 'VOID' : 'OPEN';
      }
      return json({
        event_id: 999,
        state: control.state,
        reason: 'because',
        actor_id: 'admin-1',
        updated_at: '2026-08-02T00:00:00Z',
        voided_assignments: control.state === 'VOID' ? 2 : 0,
        revision: 3,
      });
    }
    if (path.includes('/reconciliation/preview')) {
      return json({
        preview_version: '1',
        plan_id: 'plan_abc',
        current_digest: 'a',
        desired_digest: 'b',
        converged: false,
        safe_to_apply: true,
        operations: [
          {
            operation_id: 'op1',
            action: 'UPDATE',
            entity_type: 'USER_PROGRESSION',
            entity_id: 'user-1',
            impact: 'PROGRESSION_REBUILD',
            changed_fields: ['lifetime_xp', 'level'],
            before: { lifetime_xp: 0, level: 1 },
            after: { lifetime_xp: 6, level: 2 },
          },
        ],
        unchanged_entities: ['user-2'],
        blockers: [],
      });
    }
    if (path.includes('/reconciliation/apply')) {
      return json({ plan_id: 'plan_abc', applied: 1, skipped: 0, converged: true });
    }
    return json(PAYLOADS.errors.card_not_found_404, 404);
  };
  return { impl, calls };
}

function adminGateway() {
  const stub = adminStub();
  return {
    stub,
    gateway: createHttpMissionGateway({
      baseUrl: '/api',
      fetchImpl: stub.impl,
      getToken: () => 'admin-token',
    }),
  };
}

